ALTER TABLE categoria ADD COLUMN id_comercio INT NULL AFTER id_categoria, DROP INDEX nombre, ADD COLUMN nombre_general VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci GENERATED ALWAYS AS (CASE WHEN id_comercio IS NULL THEN nombre ELSE NULL END) STORED, ADD UNIQUE KEY uq_categoria_nombre_general (nombre_general), ADD UNIQUE KEY uq_categoria_comercio_nombre (id_comercio, nombre), ADD CONSTRAINT fk_categoria_comercio FOREIGN KEY (id_comercio) REFERENCES comercio (id_comercio);
